#: under-predict line breaks.
_DEFAULT_CHAR_WIDTH = 600


def string_width(text: str, font_name: str, font_size: float) -> float:
    """Estimated advance width of *text* in points.

    Mirrors ReportLab's ``stringWidth`` for the standard Helvetica /
    Helvetica-Bold / Times-Roman metrics. Unknown font names fall back to
    Helvetica; unknown characters use a conservative default width.
    """
    table = _FONT_TABLES.get(font_name, _HELVETICA_WIDTHS)
    total = 0
    for ch in text:
        total += table.get(ch, _DEFAULT_CHAR_WIDTH)
    return total * font_size / 1000.0
